<script lang="ts">
  import {onMount} from 'svelte';
  import {invoke} from '@tauri-apps/api/core';
  import type {HdrAppearance,DisplayTrial} from './api';
  let {appearance=$bindable(),connector,editable,locked,trial,hdrActive}:{appearance:HdrAppearance;connector:string;editable:boolean;locked:boolean;trial:DisplayTrial|null|undefined;hdrActive:boolean}=$props();
  let presets=$state<[string,HdrAppearance][]>([]),pattern=$state('off'),busy=$state(false),error=$state('');
  let alive=true;
  const fields=[['black_level_nits','Black level (nits)',0,0.25,0.005],['reference_white_nits','Reference white (nits)',80,10000,1],['peak_nits','Peak luminance (nits)',203,10000,1],['full_frame_peak_nits','Full-frame peak (nits)',80,10000,1],['saturation','Saturation',0.75,1.25,0.01],['midtone_gamma','Midtone gamma',0.7,1.5,0.01]] as const;
  async function show(value:string){if(!trial||busy)return;busy=true;error='';try{await invoke('set_display_trial_calibration_pattern',{previewId:trial.id,connector,pattern:value});if(alive)pattern=value;}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  $effect(()=>{if(!trial)pattern='off';});
  onMount(()=>{void invoke<[string,HdrAppearance][]>('get_hdr_presets').then(next=>{if(alive)presets=next;}).catch(cause=>{if(alive)error=String(cause);});return()=>{alive=false;if(trial)void invoke('set_display_trial_calibration_pattern',{previewId:trial.id,connector,pattern:'off'}).catch(()=>{});};});
</script>
<section class="section"><h2>HDR appearance tuning</h2><p class="description">Final HDR output appearance. Edit the draft, then Test changes. Only Keep changes saves it. Reference white and full-frame peak must not exceed peak luminance.</p>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}
<fieldset disabled={!editable||locked}><legend class="sr-only">HDR appearance draft</legend><div class="settings-card"><div class="setting-row"><div><label for="hdr-preset">Starting point</label><p>Presets are built-in starting points, not measured panel calibration.</p></div><select id="hdr-preset" value="" onchange={event=>{const preset=presets[Number(event.currentTarget.value)];if(preset)appearance={...preset[1]};event.currentTarget.value='';}}><option value="" disabled>Choose preset / reset</option>{#each presets as [label,_],index}<option value={index}>{label}</option>{/each}</select></div>{#each fields as [key,label,min,max,step]}<div class="setting-row"><label for={`hdr-${key}`}>{label}</label><input id={`hdr-${key}`} type="number" {min} {max} {step} bind:value={appearance[key]} /></div>{/each}<div class="setting-row"><label for="hdr-tone-mapper">Tone mapping</label><select id="hdr-tone-mapper" bind:value={appearance.tone_mapper}><option value="bt2390">BT.2390</option><option value="reinhard">Reinhard</option><option value="hable">Hable</option><option value="aces">ACES-inspired</option></select></div></div></fieldset>
{#if !editable}<p class="description">Enable HDR on this display in a DRM session to edit these values.</p>{/if}
<div class="settings-card pattern-card"><div class="setting-row"><div><label for="hdr-pattern">Calibration pattern</label><p>Move Settings to another display first. Available only during a confirming HDR trial; clears on Keep, Revert, or expiry.</p></div><select id="hdr-pattern" disabled={busy||!hdrActive||trial?.phase!=='confirming'} value={pattern} onchange={event=>void show(event.currentTarget.value)}><option value="off">Off</option><option value="overview">Overview</option><option value="near_black">Near-black steps</option><option value="reference_white">Reference white</option><option value="peak_window">10% peak window</option><option value="peak_full_frame">Full-field peak</option></select></div></div>
</section>
<style>fieldset{padding:0;border:0;margin:0;min-width:0}.description{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0 18px}select,input{font:inherit;font-size:12px;border:1px solid var(--fd-border);border-radius:8px;padding:9px 11px;background:var(--fd-surface);color:var(--fd-text);max-width:230px}input{width:130px}.pattern-card{margin-top:18px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}</style>
